    transform: translateY(0.5rem);
  }
  to {
    transform: translateY(0);
  }
}

:root[data-motion="reduce"] .confirm-dialog {
  animation: none;
}

@media (prefers-reduced-motion: reduce) {
  .confirm-dialog {
    animation: none;
  }
}
